import{C as s,o as a,c as n,a5 as e,E as o}from"./chunks/framework.URF5zJ_R.js";const y=JSON.parse('{"title":"42 High-Availability Architecture Building Blocks","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"en/05_Building_Blocks.md","filePath":"en/05_Building_Blocks.md","lastUpdated":1789004603000}'),i={name:"en/05_Building_Blocks.md"},f=Object.assign(i,{setup(r){const l=[{index:"01",title:"API Gateway vs Load Balancer",category:"Traffic & Access",desc:"L4/L7 load balancers distribute raw traffic; API Gateways handle routing, central auth, rate limiting, and protocol translation.",meta:{"Core Tools":"Kong · Envoy · AWS ALB · Nginx","⚠️ Anti-Pattern":"Unnecessary hops for single internal services"}},{index:"02",title:"Distributed Cache (Redis) vs In-Process Cache",category:"Caching & Speed",desc:"Redis provides shared, high-availability cache across nodes; in-process caches (Caffeine) offer nanosecond speeds but risk consistency drift.",meta:{"Core Tools":"Redis · Memcached · Caffeine","⚠️ Anti-Pattern":"Never cache strictly consistent ledger records"}},{index:"03",title:"Relational (Postgres) vs Wide-Column (Cassandra)",category:"Databases & Storage",desc:"RDBMS guarantees ACID transactions and multi-table joins; Cassandra/ScyllaDB excels at massive write throughput on trillion-row datasets.",meta:{"Core Tools":"PostgreSQL · ScyllaDB · MongoDB","⚠️ Anti-Pattern":"Avoid wide-column for complex multi-table joins"}},{index:"04",title:"Message Queue (RabbitMQ) vs Event Stream (Kafka)",category:"Messaging & Events",desc:"RabbitMQ buffers transient task queues that are deleted upon receipt; Kafka acts as an append-only replayable event log for multiple consumers.",meta:{"Core Tools":"Apache Kafka · RabbitMQ · Pulsar","⚠️ Anti-Pattern":"Avoid Kafka when a lightweight transient queue suffices"}},{index:"05",title:"Rate Limiter & Circuit Breaker",category:"Reliability & Resilience",desc:"Rate limiters protect services from traffic spikes; circuit breakers trip downstream failures quickly to prevent catastrophic cascading outages.",meta:{"Core Tools":"Envoy · Redis Token Bucket · Resilience4j","⚠️ Anti-Pattern":"Avoid limiting trusted low-latency internal RPCs"}},{index:"06",title:"Object Storage (S3) vs Block Storage (EBS)",category:"Blob & Disk Storage",desc:"S3 offers durable, cost-effective storage for immutable blobs with presigned upload URLs; EBS attaches persistent disks to compute instances.",meta:{"Core Tools":"Amazon S3 · MinIO · Cloudflare R2","⚠️ Anti-Pattern":"Avoid object stores for random sub-millisecond writes"}}];return(c,t)=>{const d=s("CardGrid");return a(),n("div",null,[t[0]||(t[0]=e('<h1 id="_42-high-availability-architecture-building-blocks" tabindex="-1">42 High-Availability Architecture Building Blocks <a class="header-anchor" href="#_42-high-availability-architecture-building-blocks" aria-label="Permalink to &quot;42 High-Availability Architecture Building Blocks&quot;">​</a></h1><blockquote><p><em>Core architectural components of modern distributed systems: roles, target use cases, anti-patterns (when NOT to use), and industry production toolsets.</em></p></blockquote><hr><div class="tip custom-block"><p class="custom-block-title">💡 Architectural Trade-offs: Anti-Patterns are the Real Scoring Key</p><p>In system design interviews, the most common pitfall is tool proliferation—defaulting to Kafka, K8s, Redis, and microservices without justification.</p><p><strong>Senior interviewers assess architectural judgment and trade-offs</strong>:</p><ul><li>Every component introduces distributed complexity (network hops, consistency trade-offs, operational failure modes).</li><li>Clearly articulating <strong>when NOT to use a component (anti-patterns)</strong> demonstrates senior engineering depth far more convincingly than merely listing features.</li></ul></div><hr><h2 id="🏛️-8-infrastructure-layers-of-distributed-systems" tabindex="-1">🏛️ 8 Infrastructure Layers of Distributed Systems <a class="header-anchor" href="#🏛️-8-infrastructure-layers-of-distributed-systems" aria-label="Permalink to &quot;🏛️ 8 Infrastructure Layers of Distributed Systems&quot;">​</a></h2><p>The 42 building blocks organize into an interconnected infrastructure hierarchy:</p><div class="stats-grid" style="margin-bottom:2rem;"><div class="stat-card"><div class="stat-icon">🚦</div><div class="stat-info"><span class="stat-number">5 Blocks</span><span class="stat-label">Traffic &amp; Gateways</span></div></div><div class="stat-card"><div class="stat-icon">⚡</div><div class="stat-info"><span class="stat-number">2 Blocks</span><span class="stat-label">Caching Tiers</span></div></div><div class="stat-card"><div class="stat-icon">🗄️</div><div class="stat-info"><span class="stat-number">11 Blocks</span><span class="stat-label">Databases &amp; Storage</span></div></div><div class="stat-card"><div class="stat-icon">📨</div><div class="stat-info"><span class="stat-number">3 Blocks</span><span class="stat-label">Messaging &amp; Events</span></div></div><div class="stat-card"><div class="stat-icon">⚙️</div><div class="stat-info"><span class="stat-number">6 Blocks</span><span class="stat-label">Compute &amp; Processing</span></div></div><div class="stat-card"><div class="stat-icon">🛡️</div><div class="stat-info"><span class="stat-number">4 Blocks</span><span class="stat-label">Reliability &amp; Resiliency</span></div></div><div class="stat-card"><div class="stat-icon">🤝</div><div class="stat-info"><span class="stat-number">4 Blocks</span><span class="stat-label">Coordination &amp; Config</span></div></div><div class="stat-card"><div class="stat-icon">🔭</div><div class="stat-info"><span class="stat-number">7 Blocks</span><span class="stat-label">Observability &amp; Security</span></div></div></div><hr><h2 id="🏆-core-architectural-trade-offs-key-building-blocks" tabindex="-1">🏆 Core Architectural Trade-offs (Key Building Blocks) <a class="header-anchor" href="#🏆-core-architectural-trade-offs-key-building-blocks" aria-label="Permalink to &quot;🏆 Core Architectural Trade-offs (Key Building Blocks)&quot;">​</a></h2><p>The 6 most frequently tested component trade-offs in technical design interviews:</p>',11)),o(d,{items:l,columns:3}),t[1]||(t[1]=e('<hr><h2 id="📚-complete-directory-42-architecture-building-blocks" tabindex="-1">📚 Complete Directory: 42 Architecture Building Blocks <a class="header-anchor" href="#📚-complete-directory-42-architecture-building-blocks" aria-label="Permalink to &quot;📚 Complete Directory: 42 Architecture Building Blocks&quot;">​</a></h2><blockquote><p><em>Use the instant filter bar above the table to search by keyword (e.g. <code>Redis</code>, <code>Kafka</code>, <code>Database</code>, <code>Lock</code>, <code>Security</code>). Automatically folds into cards on mobile.</em></p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Component</th><th style="text-align:left;">Category</th><th style="text-align:left;">Core Role</th><th style="text-align:left;">When to Use It</th><th style="text-align:left;">⚠️ When NOT to Use (Anti-Pattern)</th><th style="text-align:left;">Common Industry Tools</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Load balancer</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">Distributes requests across multiple healthy servers</td><td style="text-align:left;">Any system with more than one server</td><td style="text-align:left;">A single-instance internal tool where it adds needless complexity</td><td style="text-align:left;"><code>Nginx</code> <code>HAProxy</code> <code>AWS ALB</code> <code>Envoy</code></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Reverse proxy</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">Sits in front of servers handling TLS, routing and buffering</td><td style="text-align:left;">Terminating TLS, serving static files, hiding internal topology</td><td style="text-align:left;">When your framework already handles it well at low scale</td><td style="text-align:left;"><code>Nginx</code> <code>Caddy</code> <code>Envoy</code> <code>Traefik</code></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>API gateway</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">Single entry point handling auth, routing, rate limiting and quotas</td><td style="text-align:left;">Microservices with multiple client applications</td><td style="text-align:left;">A single service where it becomes an unnecessary network hop</td><td style="text-align:left;"><code>Kong</code> <code>AWS API Gateway</code> <code>Apigee</code> <code>Envoy</code></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>CDN</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">Caches content at edge locations near users globally</td><td style="text-align:left;">Static assets, images, video, and any global audience</td><td style="text-align:left;">Highly personalised, uncacheable dynamic content</td><td style="text-align:left;"><code>Cloudflare</code> <code>Akamai</code> <code>CloudFront</code> <code>Fastly</code></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>DNS load balancing</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">Routes users to the nearest or healthiest region</td><td style="text-align:left;">Multi-region multi-datacenter deployments</td><td style="text-align:left;">Fine-grained routing; DNS caching makes failover slow</td><td style="text-align:left;"><code>AWS Route 53</code> <code>Cloudflare DNS</code></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Application cache</strong></td><td style="text-align:left;"><code>Caching</code></td><td style="text-align:left;">In-memory storage of frequently accessed data</td><td style="text-align:left;">Read-heavy workloads with tolerable staleness</td><td style="text-align:left;">Data that must always be perfectly consistent and current</td><td style="text-align:left;"><code>Redis</code> <code>Memcached</code> <code>Valkey</code></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Local/in-process cache</strong></td><td style="text-align:left;"><code>Caching</code></td><td style="text-align:left;">Cache directly inside the application process memory</td><td style="text-align:left;">Very hot, small, rarely changing reference data</td><td style="text-align:left;">Multi-instance deployments requiring cluster-wide consistency</td><td style="text-align:left;"><code>Caffeine</code> <code>Guava</code> <code>In-memory Maps</code></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Database read replica</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Read-only copies of the primary database</td><td style="text-align:left;">Read-heavy workloads that tolerate replication lag</td><td style="text-align:left;">Read-your-writes requirements without dedicated routing</td><td style="text-align:left;"><code>PostgreSQL Streaming</code> <code>MySQL Replicas</code></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Relational database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">ACID transactions with a fixed schema and joins</td><td style="text-align:left;">Financial correctness and structured relational requirements</td><td style="text-align:left;">Extreme write scale, schema-less logs or pure key-value lookups</td><td style="text-align:left;"><code>PostgreSQL</code> <code>MySQL</code> <code>AWS Aurora</code></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>Wide-column store</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Distributed store optimised for very high write volume</td><td style="text-align:left;">Time series, event streams, messaging at massive scale</td><td style="text-align:left;">Complex queries requiring multi-table relational joins</td><td style="text-align:left;"><code>Cassandra</code> <code>ScyllaDB</code> <code>HBase</code> <code>Bigtable</code></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>Document database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Flexible schema, document-oriented storage</td><td style="text-align:left;">Evolving schemas, nested documents and agile models</td><td style="text-align:left;">Heavy relational joins and multi-document ACID transactions</td><td style="text-align:left;"><code>MongoDB</code> <code>DynamoDB</code> <code>Firestore</code></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>Key-value store</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Simple, sub-millisecond lookups by primary key</td><td style="text-align:left;">Sessions, caching, feature flags, simple lookups</td><td style="text-align:left;">Any query requiring non-primary-key range or full-text filters</td><td style="text-align:left;"><code>Redis</code> <code>DynamoDB</code> <code>etcd</code></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>Graph database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Stores and traverses relationships as first-class data</td><td style="text-align:left;">Social graphs, fraud rings, recommendation engines</td><td style="text-align:left;">Simple tabular data with no multi-hop traversal requirements</td><td style="text-align:left;"><code>Neo4j</code> <code>AWS Neptune</code> <code>JanusGraph</code></td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>Time-series database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Optimised for timestamped metrics with downsampling</td><td style="text-align:left;">Monitoring, IoT sensors, financial tick streams</td><td style="text-align:left;">General-purpose transactional data with frequent row updates</td><td style="text-align:left;"><code>InfluxDB</code> <code>TimescaleDB</code> <code>Prometheus</code></td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>Search index</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Inverted index for full-text search, faceting and ranking</td><td style="text-align:left;">Any product with a search box and multi-facet filtering</td><td style="text-align:left;">Exact lookups where primary database keys suffice</td><td style="text-align:left;"><code>Elasticsearch</code> <code>OpenSearch</code> <code>Typesense</code> <code>Solr</code></td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>OLAP / data warehouse</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">Columnar storage for analytical aggregation at scale</td><td style="text-align:left;">Dashboards, reporting, business analytics and BI</td><td style="text-align:left;">Low-latency point lookups or transactional row-level updates</td><td style="text-align:left;"><code>Snowflake</code> <code>BigQuery</code> <code>ClickHouse</code> <code>Redshift</code></td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>Object storage</strong></td><td style="text-align:left;"><code>Storage</code></td><td style="text-align:left;">High-durability, low-cost storage for large blobs</td><td style="text-align:left;">Images, video, backups, data lakes</td><td style="text-align:left;">Low-latency random access or transactional data</td><td style="text-align:left;"><code>Amazon S3</code> <code>Google Cloud Storage</code> <code>MinIO</code></td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>Block storage</strong></td><td style="text-align:left;"><code>Storage</code></td><td style="text-align:left;">Persistent disk attached to a compute instance</td><td style="text-align:left;">Databases and anything needing a filesystem</td><td style="text-align:left;">Sharing across many instances simultaneously over networks</td><td style="text-align:left;"><code>AWS EBS</code> <code>GCP Persistent Disk</code></td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>Message queue</strong></td><td style="text-align:left;"><code>Messaging</code></td><td style="text-align:left;">Buffers work between producer and consumer</td><td style="text-align:left;">Decoupling services, absorbing spikes, background jobs</td><td style="text-align:left;">Genuinely synchronous request-response requirements</td><td style="text-align:left;"><code>RabbitMQ</code> <code>AWS SQS</code> <code>Redis Streams</code></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>Event log / stream</strong></td><td style="text-align:left;"><code>Messaging</code></td><td style="text-align:left;">Durable, replayable, ordered append-only log</td><td style="text-align:left;">Event sourcing, multiple independent consumers, replay</td><td style="text-align:left;">Simple transient task queues where it is complete overkill</td><td style="text-align:left;"><code>Apache Kafka</code> <code>Pulsar</code> <code>AWS Kinesis</code> <code>Redpanda</code></td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>Pub/sub</strong></td><td style="text-align:left;"><code>Messaging</code></td><td style="text-align:left;">One publisher, many independent subscribers</td><td style="text-align:left;">Fan-out notifications and event broadcasting</td><td style="text-align:left;">Guaranteed single-consumer exclusive processing</td><td style="text-align:left;"><code>Kafka</code> <code>Google Cloud Pub/Sub</code> <code>AWS SNS</code> <code>NATS</code></td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>Task scheduler</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">Runs jobs on a schedule or after a delay</td><td style="text-align:left;">Reports, cleanups, reminders, retries</td><td style="text-align:left;">Immediate synchronous work requiring millisecond returns</td><td style="text-align:left;"><code>Apache Airflow</code> <code>Temporal</code> <code>Quartz</code> <code>cron</code></td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>Worker pool</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">Processes queued jobs asynchronously</td><td style="text-align:left;">Any computation too slow for the HTTP request cycle</td><td style="text-align:left;">Sub-millisecond synchronous compute operations</td><td style="text-align:left;"><code>Celery</code> <code>Sidekiq</code> <code>BullMQ</code> <code>Hangfire</code></td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>Serverless functions</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">Event-triggered compute with no server management</td><td style="text-align:left;">Spiky, low-volume, event-driven workloads</td><td style="text-align:left;">Long-running tasks or work sensitive to cold-start latency</td><td style="text-align:left;"><code>AWS Lambda</code> <code>Cloud Functions</code> <code>Azure Functions</code></td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>Container orchestrator</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">Schedules, scales and heals containerised services</td><td style="text-align:left;">Multi-service systems operating at meaningful scale</td><td style="text-align:left;">A single small service where Kubernetes overhead dominates</td><td style="text-align:left;"><code>Kubernetes</code> <code>AWS ECS</code> <code>Nomad</code></td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>Stream processor</strong></td><td style="text-align:left;"><code>Processing</code></td><td style="text-align:left;">Continuous computation over event streams</td><td style="text-align:left;">Real-time fraud detection, windowing, stream enrichment</td><td style="text-align:left;">Batch work with no real-time latency requirement</td><td style="text-align:left;"><code>Apache Flink</code> <code>Kafka Streams</code> <code>Spark Streaming</code></td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>Batch processor</strong></td><td style="text-align:left;"><code>Processing</code></td><td style="text-align:left;">Large-scale scheduled data processing</td><td style="text-align:left;">Nightly reports, ETL pipelines, model training data</td><td style="text-align:left;">Anything needing sub-minute data freshness</td><td style="text-align:left;"><code>Apache Spark</code> <code>Hadoop</code> <code>dbt</code> <code>Airflow</code></td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>Rate limiter</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">Caps request rate per user, key or tenant</td><td style="text-align:left;">Any public API or abuse-prone endpoint</td><td style="text-align:left;">Trusted internal traffic with known controlled volume</td><td style="text-align:left;"><code>Redis Token Bucket</code> <code>Envoy</code> <code>API Gateway</code></td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>Circuit breaker</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">Stops calling a failing dependency to allow recovery</td><td style="text-align:left;">Any synchronous remote call to another service</td><td style="text-align:left;">Local in-process function calls</td><td style="text-align:left;"><code>Resilience4j</code> <code>Polly</code> <code>Envoy</code> <code>Hystrix</code></td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>Service discovery</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">Lets services find each other dynamically</td><td style="text-align:left;">Dynamic environments where instances come and go</td><td style="text-align:left;">Fixed, small, static server deployments</td><td style="text-align:left;"><code>HashiCorp Consul</code> <code>Eureka</code> <code>K8s CoreDNS</code></td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>Service mesh</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">Handles service-to-service traffic, security and telemetry</td><td style="text-align:left;">Large microservice estates (20+ services)</td><td style="text-align:left;">Fewer than about ten services where mesh overhead dominates</td><td style="text-align:left;"><code>Istio</code> <code>Linkerd</code> <code>Consul Connect</code></td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>Distributed lock</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">Ensures only one process performs an action</td><td style="text-align:left;">Leader election, preventing duplicate job execution</td><td style="text-align:left;">When simple idempotency or DB constraints solve it cleanly</td><td style="text-align:left;"><code>Redis Redlock</code> <code>Apache ZooKeeper</code> <code>etcd</code></td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>Consensus / coordination service</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">Agreement on shared state across nodes</td><td style="text-align:left;">Leader election, configuration, cluster membership</td><td style="text-align:left;">Simple systems where a database suffices</td><td style="text-align:left;"><code>Apache ZooKeeper</code> <code>etcd</code> <code>Consul</code></td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>Configuration service</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">Centralised, dynamic application configuration</td><td style="text-align:left;">Many services needing consistent, changeable config</td><td style="text-align:left;">A single service where environment variables work</td><td style="text-align:left;"><code>Spring Cloud Config</code> <code>Consul</code> <code>AWS AppConfig</code></td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>Feature flag service</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">Toggles behaviour without a deployment</td><td style="text-align:left;">Gradual rollouts, kill switches, experiments</td><td style="text-align:left;">Very small teams shipping infrequently</td><td style="text-align:left;"><code>LaunchDarkly</code> <code>Unleash</code> <code>Flagsmith</code></td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>Metrics and monitoring</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">Collects and stores numeric time-series signals</td><td style="text-align:left;">Every production system without exception</td><td style="text-align:left;">Never; this is not optional in production</td><td style="text-align:left;"><code>Prometheus</code> <code>Grafana</code> <code>Datadog</code> <code>CloudWatch</code></td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>Distributed tracing</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">Follows a single request across many services</td><td style="text-align:left;">Any system with more than about three microservices</td><td style="text-align:left;">A monolith where local logs suffice</td><td style="text-align:left;"><code>OpenTelemetry</code> <code>Jaeger</code> <code>Tempo</code> <code>Zipkin</code></td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>Centralised logging</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">Aggregates and indexes logs from all services</td><td style="text-align:left;">Any multi-instance deployment</td><td style="text-align:left;">A single server you can easily SSH into</td><td style="text-align:left;"><code>Elasticsearch (ELK)</code> <code>Grafana Loki</code> <code>Splunk</code></td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>Error tracking</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">Captures, groups and alerts on exceptions</td><td style="text-align:left;">Every user-facing application</td><td style="text-align:left;">Never; free tiers make integration trivial</td><td style="text-align:left;"><code>Sentry</code> <code>Rollbar</code> <code>Bugsnag</code></td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>Identity provider</strong></td><td style="text-align:left;"><code>Security</code></td><td style="text-align:left;">Centralised authentication and token issuance</td><td style="text-align:left;">Any system with users, especially multi-service</td><td style="text-align:left;">A single app with simple session auth</td><td style="text-align:left;"><code>Auth0</code> <code>Keycloak</code> <code>Microsoft Entra ID</code> <code>Cognito</code></td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>Secrets manager</strong></td><td style="text-align:left;"><code>Security</code></td><td style="text-align:left;">Stores and rotates credentials securely</td><td style="text-align:left;">Every production system</td><td style="text-align:left;">Never; hardcoding credentials in Git is a critical vulnerability</td><td style="text-align:left;"><code>HashiCorp Vault</code> <code>AWS Secrets Manager</code> <code>Doppler</code></td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>WAF / DDoS protection</strong></td><td style="text-align:left;"><code>Security</code></td><td style="text-align:left;">Filters malicious traffic at the edge</td><td style="text-align:left;">Any public-facing service</td><td style="text-align:left;">Internal-only services behind a private VPN</td><td style="text-align:left;"><code>Cloudflare WAF</code> <code>AWS WAF</code> <code>Akamai</code></td></tr></tbody></table><hr>',5))])}}});export{y as __pageData,f as default};
